customCSS:
.t, .history { color: #6dceeb; }
.join { color: #89fb98; }
.part, .quit { color: #6dceeb; }
.kick, .error { color: #ff0000; }
.notice { color: #f0e68c; }
.action { color: #ffde9b; }
.mode, .nick, .topic, .server { color: #6dceeb; }
.highlight { color: #ffffff; background-color: #6b8e24; border-left: 3px solid #ffde9b; padding-left: 8px; }
.reply { color: #6dceeb; border-left: 2px solid #75a0ff; padding-left: 6px; }
.oper { color: #333333; background-color: #f0e68c; }
.reactions { color: #75a0ff; background-color: #4d4d4d; }
.card { background-color: #4d4d4d; border-color: #6dceeb; }
.card-title { color: #75a0ff; }
.card-desc { color: #6dceeb; }
.daychange { color: #6dceeb; border-color: #4d4d4d; }
